-- Rasterise original polygon letterforms locally, so the logo needs no uploaded asset.
local glyphs = {
	W = { { {0,0},{13,0},{21,54},{30,25},{39,54},{47,0},{60,0},{46,80},{34,80},{30,59},{26,80},{14,80} } },
	A = { { {0,80},{18,0},{42,0},{60,80},{44,80},{39,60},{21,60},{16,80} }, { {25,44},{35,44},{30,19} } },
	R = { { {0,0},{44,0},{60,14},{60,36},{46,50},{64,80},{46,80},{28,50},{16,50},{16,80},{0,80} }, { {16,16},{40,16},{44,20},{44,30},{40,34},{16,34} } },
	F = { { {0,0},{58,0},{58,16},{16,16},{16,32},{49,32},{49,48},{16,48},{16,80},{0,80} } },
	O = { { {14,0},{46,0},{60,14},{60,66},{46,80},{14,80},{0,66},{0,14} }, { {20,16},{40,16},{44,20},{44,60},{40,64},{20,64},{16,60},{16,20} } },
	N = { { {0,80},{0,0},{16,0},{44,50},{44,0},{60,0},{60,80},{44,80},{16,30},{16,80} } },
	T = { { {0,0},{60,0},{60,16},{38,16},{38,80},{22,80},{22,16},{0,16} } },
}
local function inside(points, x, y)
	local hit, j = false, #points
	for i, p in points do
		local q = points[j]
		if (p[2] > y) ~= (q[2] > y) and x < (q[1] - p[1]) * (y - p[2]) / (q[2] - p[2]) + p[1] then hit = not hit end
		j = i
	end
	return hit
end

function MapMenu.wordmark(parent, name)
	if not logoImage then
		local ok, image = pcall(function()
			local img = game:GetService("AssetService"):CreateEditableImage({ Size = Vector2.new(556, 80) })
			if not img then return nil end
			local pixels = buffer.create(556 * 80 * 4)
			local x0 = 0
			for i = 1, 8 do
				local letter = string.sub("WARFRONT", i, i)
				local g = glyphs[letter]
				local colour = if i <= 3 then C.WHITE else C.MALIBU
				for y = 0, 79 do
					for x = 0, 63 do
						local fill = inside(g[1], x + 0.5, y + 0.5) and (not g[2] or not inside(g[2], x + 0.5, y + 0.5))
						-- Two deliberate junction cuts distinguish this from a standard font.
						if (letter == "R" and x > 38 and y > 37 and y < 42) or (letter == "F" and x > 9 and x < 19 and y > 29 and y < 34) then fill = false end
						if fill then
							local at = (y * 556 + x0 + x) * 4
							local top=if i<=3 then Color3.fromRGB(255,255,255) else Color3.fromRGB(58,215,255)
							local bottom=if i<=3 then Color3.fromRGB(190,204,220) else Color3.fromRGB(0,113,194)
							local shade=top:Lerp(bottom,y/79)
							local topEdge=not inside(g[1],x+0.5,y-0.5) or (g[2] and inside(g[2],x+0.5,y-0.5))
							local bottomEdge=not inside(g[1],x+0.5,y+1.5) or (g[2] and inside(g[2],x+0.5,y+1.5))
							if topEdge then shade=shade:Lerp(C.WHITE,0.55) elseif bottomEdge then shade=shade:Lerp(C.BLACK,0.28) end
							buffer.writeu8(pixels, at, math.round(shade.R * 255))
							buffer.writeu8(pixels, at + 1, math.round(shade.G * 255))
							buffer.writeu8(pixels, at + 2, math.round(shade.B * 255))
							buffer.writeu8(pixels, at + 3, 255)
						end
					end
				end
				x0 += if i == 3 then 80 else 68
			end
			img:WritePixelsBuffer(Vector2.zero, img.Size, pixels)
			return img
		end)
		if ok then logoImage = image end
	end
	if logoImage then
		return make("ImageLabel", { Name = name, BackgroundTransparency = 1, ScaleType = Enum.ScaleType.Fit, ImageContent = Content.fromObject(logoImage), Parent = parent })
	end
	return Kit.text({ Name = name, Text = "WAR FRONT", FontFace = F.BLACK, TextScaled = true, Parent = parent })
end


