local function flatIcon(parent, kind, colour)
	local image = iconImages[kind]
	if image == nil then
		local ok, result = pcall(function()
			if kind=="hourglass" then
				local image=game:GetService("AssetService"):CreateEditableImage({Size=Vector2.new(512,512)})
				if not image then return nil end
				local pixels=buffer.create(512*512*4)
				local at=0
				for index=1,#HOURGLASS_ALPHA,6 do
					local alpha=tonumber(HOURGLASS_ALPHA:sub(index,index+1),16)
					local run=tonumber(HOURGLASS_ALPHA:sub(index+2,index+5),16)
					for _=1,run do buffer.writeu32(pixels,at,16777215+alpha*16777216);at+=4 end
				end
				image:WritePixelsBuffer(Vector2.zero,image.Size,pixels)
				return image
			end
			local img = game:GetService("AssetService"):CreateEditableImage({Size=Vector2.new(128,128)})
			if not img then return nil end
			local pixels=buffer.create(128*128*4)
			for py=0,127 do
				for px=0,127 do
					local x,y=(px+0.5)*44/128,(py+0.5)*44/128
					local fill=false
					if kind=="solo" then
						fill=(x-22)^2+(y-11)^2<8^2 or (y>=28 and y<=42 and x>=8 and x<=36) or (y>=24 and y<32 and (x-22)^2+(y-34)^2<14^2)
					elseif kind=="people" then
						fill=(x-13)^2+(y-13)^2<6^2 or (x-31)^2+(y-13)^2<6^2 or (y>=29 and y<=39 and x>=3 and x<=23) or (y>=29 and y<=39 and x>=25 and x<=42) or (y>=24 and y<31 and (x-13)^2+(y-32)^2<10^2) or (y>=24 and y<31 and (x-33)^2+(y-32)^2<9^2)
					elseif kind=="clock" then
						local r=(x-22)^2+(y-24)^2
						fill=(r<16^2 and r>13^2) or (x>=21 and x<=24 and y>=13 and y<=26) or (x>=22 and x<=31 and y>=24 and y<=27) or (x>=17 and x<=27 and y>=2 and y<=6)
					else
						for _,polygon in iconShapes[kind] do if inside(polygon,x,y) then fill=true;break end end
					end
					if fill then buffer.writeu32(pixels,(py*128+px)*4,4294967295) end
				end
			end
			img:WritePixelsBuffer(Vector2.zero,img.Size,pixels)
			return img
		end)
		iconImages[kind] = if ok and result then result else false
		image = iconImages[kind]
	end
	if image then
		return make("ImageLabel",{Name="FlatIcon",BackgroundTransparency=1,ImageContent=Content.fromObject(image),ImageColor3=colour,ImageRectOffset=if kind=="hourglass" then Vector2.new(98,26) else Vector2.zero,ImageRectSize=if kind=="hourglass" then Vector2.new(319,460) else Vector2.zero,ScaleType=Enum.ScaleType.Fit,ZIndex=4,Parent=parent})
	end
	return Kit.icon(if kind=="solo" then "User" elseif kind=="trophy" then "Crown" elseif kind=="book" then "Help" else "People",{Name="FlatIcon",ImageColor3=colour,ZIndex=4,Parent=parent})
end
local function outline(parent,colour,thickness)
	return Kit.stroke(parent,0,colour,thickness or 1.5)
end
local function caption(parent,name,value,size,colour)
	return Kit.text({Name=name,Text=value,FontFace=DISPLAY_FONT,TextSize=size,TextColor3=colour or C.WHITE,TextStrokeColor3=C.BLACK,TextStrokeTransparency=0.45,TextTruncate=Enum.TextTruncate.AtEnd,ZIndex=4,Parent=parent})
end

local primaryShape
local function primaryArtwork(b,colour)
	if not primaryShape then
		local ok,img=pcall(function()
			local image=game:GetService("AssetService"):CreateEditableImage({Size=Vector2.new(256,64)})
			if not image then return nil end
			local pixels=buffer.create(256*64*4)
			local function filled(x,y)
				if x<0 or x>=256 or y<0 or y>=64 then return false end
				if x>238+y and y<18 then return false end
				if x<6 and y<6 then return (x-6)^2+(y-6)^2<=36 end
				if x<6 and y>58 then return (x-6)^2+(y-58)^2<=36 end
				if x>250 and y>58 then return (x-250)^2+(y-58)^2<=36 end
				return true
			end
			for y=0,63 do for x=0,255 do
				if filled(x,y) then
					local edge=not filled(x-1,y) or not filled(x+1,y) or not filled(x,y-1) or not filled(x,y+1)
					local k=if edge then 255 else 235
					buffer.writeu32(pixels,(y*256+x)*4,k+k*256+k*65536+255*16777216)
				end
			end end
			image:WritePixelsBuffer(Vector2.zero,image.Size,pixels)
			return image
		end)
		primaryShape=if ok then img else nil
	end
	if primaryShape then
		local img=make("ImageLabel",{Name="PrimaryShape",BackgroundTransparency=1,ImageContent=Content.fromObject(primaryShape),ImageColor3=C.WHITE,Size=UDim2.fromScale(1,1),ZIndex=3,Parent=b})
		b.BackgroundTransparency=1
		local st=b:FindFirstChildWhichIsA("UIStroke");if st then st.Enabled=false end
		local gradient=make("UIGradient",{Name="SurfaceGradient",Rotation=90,Parent=img})
		local function paintGradient()
			local base=b.BackgroundColor3
			local top=base:Lerp(C.WHITE,0.18)
			local bottom=if colour==C.CYBER then base:Lerp(Color3.fromRGB(244,159,0),0.78) else base:Lerp(Color3.fromRGB(0,94,180),0.65)
			gradient.Color=ColorSequence.new(top,bottom)
		end
		b:GetPropertyChangedSignal("BackgroundColor3"):Connect(paintGradient)
		paintGradient()
	end
end


local hexImage
local function hexFade(parent)
	if not hexImage then
		local ok,result=pcall(function()
			local img=game:GetService("AssetService"):CreateEditableImage({Size=Vector2.new(256,64)})
			if not img then return nil end
			local pixels=buffer.create(256*64*4)
			for y=0,63 do for x=0,255 do
				local row=math.floor(y/20)
				local cx=math.floor((x-(row%2)*12)/24)*24+(row%2)*12+12
				local cy=row*20+10
				local dx,dy=math.abs(x-cx),math.abs(y-cy)
				-- A thin hex outline; transparency falls steadily toward the right.
				local edge=math.max(dx/10,(dx+dy*1.732)/20)
				if edge>=0.91 and edge<=1.04 then
					local a=math.floor(160*(1-x/256))
					buffer.writeu32(pixels,(y*256+x)*4,16777215+a*16777216)
				end
			end end
			img:WritePixelsBuffer(Vector2.zero,img.Size,pixels)
			return img
		end)
		if ok then hexImage=result end
	end
	if hexImage then
		make("ImageLabel",{Name="HexFade",BackgroundTransparency=1,ImageContent=Content.fromObject(hexImage),ImageColor3=Color3.fromRGB(164,211,255),ImageTransparency=0.83,Position=UDim2.fromScale(0.025,0.06),Size=UDim2.fromScale(0.90,0.88),ZIndex=3,Parent=parent})
	end
end

local cutImages={}
local function cutButtonImage(colour)
 local key=tostring(colour)
 if cutImages[key] then return cutImages[key] end
 local ok,img=pcall(function()
  local w,h,slant=512,96,36
  local image=game:GetService("AssetService"):CreateEditableImage({Size=Vector2.new(w,h)})
  if not image then return nil end
  local pixels=buffer.create(w*h*4)
  for y=0,h-1 do
   local left=slant*(1-y/(h-1));local right=w-1-slant*y/(h-1)
   for x=math.ceil(left),math.floor(right) do
    local edge=math.min(y,h-1-y,(x-left)/1.12,(right-x)/1.12)
    local fill=if edge<2 then colour:Lerp(C.WHITE,0.35) else colour:Lerp(Color3.new(0,0,0),0.18*y/(h-1))
    local o=(y*w+x)*4
    buffer.writeu8(pixels,o,math.round(fill.R*255));buffer.writeu8(pixels,o+1,math.round(fill.G*255));buffer.writeu8(pixels,o+2,math.round(fill.B*255));buffer.writeu8(pixels,o+3,255)
   end
  end
  image:WritePixelsBuffer(Vector2.zero,image.Size,pixels)
  return image
 end)
 if ok and img then cutImages[key]=img;return img end
 return nil
end

local function restyleButton(b,colour,kind)
	local shape=b:FindFirstChild("AngularShape")
	if shape then shape.Visible=false end
	local label=b:FindFirstChild("Label")
	if label then label.Visible=false end
	b.BackgroundColor3=colour
	b.BackgroundTransparency=0
	b.TextTransparency=1
	b.AutoButtonColor=false
	make("UIGradient",{Name="SurfaceGradient",Rotation=90,Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(205,218,235)),Parent=b})
	local corners=b:FindFirstChildWhichIsA("UICorner")
	local radius=if kind=="solo" or kind=="book" then 0 else 12
	if corners then corners.CornerRadius=UDim.new(0,radius) else Kit.corner(b,radius) end
	local stroke=b:FindFirstChildWhichIsA("UIStroke")
	if stroke then stroke.Color=MUTED;stroke.Transparency=0.45 else stroke=Kit.stroke(b,0.45,MUTED,1.5) end
	local primary=kind=="solo" or kind=="book"
 local coloured=kind=="create" or kind=="trophy" or kind=="join"
 if coloured then
  b.SurfaceGradient.Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(210,218,230))
  stroke.Color=colour:Lerp(C.WHITE,0.35);stroke.Transparency=0.15
 end
 if coloured then
  local fade=b:FindFirstChild("HexFade");if fade then fade:Destroy() end
 end
 if primary then
  hexFade(b)
  local fade=b:FindFirstChild("HexFade")
  if fade then fade.ImageColor3=colour:Lerp(C.WHITE,0.75);fade.ImageTransparency=0.65 end
 end
	stroke.Thickness=2
	if primary then stroke.Color=colour:Lerp(C.WHITE,0.35);stroke.Transparency=0.1 end
 local cutSurface
 if primary then
  local image=cutButtonImage(colour)
  if image then
   cutSurface=make("ImageLabel",{Name="CutSurface",BackgroundTransparency=1,Size=UDim2.fromScale(1,1),ImageContent=Content.fromObject(image),ZIndex=2,Parent=b})
   b.BackgroundTransparency=1;stroke.Enabled=false
  end
  local fade=b:FindFirstChild("HexFade")
  if fade then fade.Position=UDim2.fromScale(0.14,0.06);fade.Size=UDim2.fromScale(0.72,0.88) end
 end
	local fg=colour:Lerp(Color3.fromRGB(245,249,255),0.86)
	local labelNew=caption(b,"Caption",b.Text,20,fg)
	labelNew.TextStrokeColor3=Color3.new(0,0,0);labelNew.TextStrokeTransparency=0.5;labelNew.FontFace=DISPLAY_FONT
	b:GetPropertyChangedSignal("Text"):Connect(function() labelNew.Text=b.Text end)
	Kit.hover(b,function(s)
		local fill=if s=="press" then colour:Lerp(C.BLACK,0.15) elseif s=="hover" then colour:Lerp(C.WHITE,0.1) else colour
  b.BackgroundColor3=fill
  if cutSurface then
   b.BackgroundTransparency=1
   cutSurface.ImageColor3=if s=="hover" then Color3.new(1,1,1) elseif s=="press" then Color3.fromRGB(220,220,220) else Color3.fromRGB(246,246,246)
  end
	end)
	return {caption=labelNew,secondary=coloured}
end
local function buttonLayout(parts,w,h,size)
 size=math.floor(size*1.1+0.5)
 local textW=game:GetService("TextService"):GetTextSize(parts.caption.Text,size,Enum.Font.GothamBlack,Vector2.new(10000,h)).X+4
 while textW>w-24 and size>12 do
  size-=1
  textW=game:GetService("TextService"):GetTextSize(parts.caption.Text,size,Enum.Font.GothamBlack,Vector2.new(10000,h)).X+4
 end
 parts.caption.TextSize=size
 parts.caption.TextXAlignment=Enum.TextXAlignment.Center
 parts.caption.TextTruncate=Enum.TextTruncate.None
 place(parts.caption,12,0,w-24,h)
end

local function refresh()
	if not ctx or not ui.root.Visible then return end
	for i,c in ctx.cards do
		local card=ui.cards[i]
		card.button.Visible=c.mapId~=nil and (i==1 or c.button.Visible) and (not ui.mobile or i==1)
		card.title.Text=c.title.Text
		card.mode.Text=c.sub.Text
		card.count.Text=c.count.Text:gsub("/"," / ")
		if ui.width then
			local region=PREVIEW_REGIONS[c.mapId]
			if region and ui.artwork then
				local pw,ph=card.picture.Size.X.Offset,card.picture.Size.Y.Offset
				local mapWidth=pw-20
				local scale=math.min(mapWidth/(region[3]*BACKGROUND_SIZE.X),(ph-20)/(region[4]*BACKGROUND_SIZE.Y))
				local aw,ah=BACKGROUND_SIZE.X*scale,BACKGROUND_SIZE.Y*scale
				place(card.artClip,10+(mapWidth-region[3]*aw)/2,(ph-region[4]*ah)/2,region[3]*aw,region[4]*ah)
				place(card.art,-region[1]*aw,-region[2]*ah,aw,ah)
			end
		end
		card.timerValue.Text=c.timer.Text
		card.timer.Visible=c.timer.Visible
		local queuing=ctx.isQueued and ctx.isQueued(c) or false
		card.join:SetAttribute("Queuing",queuing)
		card.join.Text=if queuing then "QUEUING" elseif c.mode=="vote" then "VOTE" elseif c.mode=="pool" then "VIEW" else "JOIN"
		local chosen=c==selected
  local joinColour=if queuing then QUEUE_ORANGE elseif chosen then ACCENT else Color3.fromRGB(59,88,119)
  card.join:SetAttribute("IdleColour",joinColour);card.join.BackgroundColor3=joinColour
  card.joinCaption.TextColor3=if queuing then INK else C.WHITE
  card.join:FindFirstChildWhichIsA("UIGradient").Color=ColorSequence.new(Color3.new(1,1,1),if queuing then Color3.fromRGB(255,170,89) else Color3.fromRGB(133,179,211))
  card.join:FindFirstChildWhichIsA("UIStroke").Color=if queuing then Color3.fromRGB(255,205,105) elseif chosen then Color3.fromRGB(56,213,255) else Color3.fromRGB(102,139,178)
		local hex=card.join:FindFirstChild("HexFade")
		if hex then
			hex.ImageColor3=if queuing then Color3.fromRGB(255,230,164) else Color3.fromRGB(164,211,255)
			hex.ImageTransparency=if queuing then 0.72 else 0.83
		end
		card.stroke.Color=if chosen then ACCENT else Color3.fromRGB(89,123,160)
		card.stroke.Transparency=if chosen then 0 else 0.12
		card.stroke.Thickness=if chosen then 3 else 2
		local custom=THUMBNAIL_REGIONS[c.mapId]
  card.custom.Visible=custom~=nil
  if custom then
   card.custom.Image=custom[5] or THUMBNAIL_ASSET
   card.custom.ImageRectOffset=Vector2.new(custom[1],custom[2]);card.custom.ImageRectSize=Vector2.new(custom[3],custom[4])
  end
  local preview=if c.mapId and not custom then ctx.preview(c.mapId,512,true) else nil
  card.region=PREVIEW_REGIONS[c.mapId]
