local function layoutCard(card,x,y,w,h,font)
 place(card.button,x,y,w,h)
 local footer=math.max(126,h*0.42,font*1.35+math.clamp(font*1.3,24,32)+math.clamp(h*0.14,34,50)+math.clamp(w*0.052,12,20)+24)
 local pictureH=h-footer
 local pad=math.clamp(w*0.052,12,20)
 place(card.picture,1,1,w-2,pictureH)
 place(card.preview,10,10,w-22,pictureH-20)
 place(card.custom,10,10,w-22,pictureH-20)
 local jw=math.floor(w*0.36)
 local joinX=w-pad-jw
 local joinH=math.clamp(h*0.14,34,50)
 local joinY=h-pad-joinH
 local timerH=math.clamp(font*1.3,24,32)
 place(card.timer,joinX,joinY-timerH-8,jw,timerH)
 place(card.timerValue,0,0,jw,timerH);card.timerValue.TextSize=math.clamp(font*0.72,16,22)
 card.timer.ClipsDescendants=false
 place(card.title,pad,pictureH+8,w-2*pad,font*1.35);card.title.TextSize=font
 place(card.mode,pad,joinY-timerH-8,joinX-pad-8,timerH);card.mode.TextSize=math.clamp(font*0.67,13,20)
 local iconSize=math.clamp(font*0.8,20,26)
 place(card.people,pad,joinY+(joinH-iconSize)/2,iconSize,iconSize)
 place(card.count,pad+iconSize+10,joinY,joinX-pad-iconSize-18,joinH);card.count.TextSize=math.clamp(font*0.7,14,21)
 place(card.join,joinX,joinY,jw,joinH)
 card.join.TextSize=math.clamp(font*0.75,16,22)
 place(card.joinCaption,0,0,jw,joinH);card.joinCaption.TextSize=card.join.TextSize
 card.joinCaption.TextXAlignment=Enum.TextXAlignment.Center
end

