function MapMenu.show(visible,w,h,navH,queueH,backgroundOnly)
	if not ctx then return end
	ui.root.Visible=visible or backgroundOnly == true
	ui.root.ZIndex=if backgroundOnly then 0 else 1
	ui.body.Visible=visible
	ui.profile.Visible=false
	if not visible and ui.utility then ui.utility.BackgroundTransparency=0.05 end
	if visible or backgroundOnly then MapMenu.layout(w,h,navH,queueH);refresh() end
end
function MapMenu.update()
	refresh()
	if ctx and ui.root.Visible then MapMenu.layout(ui.width,ui.height,ui.navH,ui.queueH) end
end
return MapMenu
